// Arma el JSON final que consume el frontend (vía proxy Django)
const r = $input.first().json;
const webhookQuery = $('Webhook Historico').first().json.query || {};

const hoy = r.hoy_valor != null ? Number(r.hoy_valor.toFixed ? r.hoy_valor.toFixed(2) : r.hoy_valor) : null;
const promedio = r.promedio_historico != null ? Number(r.promedio_historico.toFixed ? r.promedio_historico.toFixed(2) : r.promedio_historico) : null;
const desviacion = r.desviacion != null ? Number(r.desviacion.toFixed ? r.desviacion.toFixed(2) : r.desviacion) : null;
const nDias = r.n_dias || 0;

let diferenciaPct = null;
if (hoy != null && promedio) {
  diferenciaPct = Number((((hoy - promedio) / promedio) * 100).toFixed(1));
}

const serieSemanas = (r.serie_semanas || []).map(s => ({ semana: s.semana, valor: s.valor != null ? Number(s.valor.toFixed ? s.valor.toFixed(2) : s.valor) : null }));
if (hoy != null) serieSemanas.push({ semana: 'Hoy', valor: hoy });

return [{
  json: {
    ok: true,
    sector: webhookQuery.sector,
    variable: webhookQuery.variable,
    lat: Number(webhookQuery.lat),
    lon: Number(webhookQuery.lon),
    hoy: { valor: hoy },
    promedio_historico: { valor: promedio, desviacion, n_dias: nDias },
    diferencia_pct: diferenciaPct,
    serie_semanas: serieSemanas,
  }
}];
